MS_DAY = 86400000
TRANSIT_MAX_MS = 4999
OFFSET_LIMIT = 19
GIB = 1 << 30
MIB = 1 << 20
REGIONS = ["central", "east", "north", "south", "west"]
SEGMENTS = ["consumer", "corporate", "enterprise", "smb"]
QUIET_START_MS = (2 * 3600 + 55 * 60) * 1000   # 02:55 UTC, no query activity
QUIET_END_MS = (3 * 3600 + 17 * 60) * 1000     # 03:17 UTC
STEP_AT_MS = (3 * 3600 + 6 * 60) * 1000        # a clock step happens at 03:06 UTC
STEP_GAP_MS = 150000

ZONE_POOL = {
    "Z-ATL": {"std": -300, "dst": -240, "rule": "us"},
    "Z-CHI": {"std": -360, "dst": -300, "rule": "us"},
    "Z-LON": {"std": 0, "dst": 60, "rule": "eu"},
    "Z-BER": {"std": 60, "dst": 120, "rule": "eu"},
    "Z-DEL": {"std": 330, "dst": None, "rule": None},
    "Z-SGP": {"std": 480, "dst": None, "rule": None},
}
PLAN_POOL = {
    "PL-STARTER": (24 * GIB, 10000000, 1 * MIB, 6103, 3051),
    "PL-TEAM": (160 * GIB, 30000000, 4 * MIB, 5493, 2747),
    "PL-BUSINESS": (600 * GIB, 60000000, 8 * MIB, 4883, 2443),
    "PL-SCALE": (2048 * GIB, 125000000, 16 * MIB, 4273, 2137),
    "PL-GROWTH": (320 * GIB, 45000000, 4 * MIB, 5189, 2593),
    "PL-RESEARCH": (90 * GIB, 15000000, 2 * MIB, 3967, 1983),
}
PRODUCT_LINES = ["lakehouse", "warehouse", "streaming", "federated", "feature-store", "archive", "geospatial"]


def ms_of(y, mo, d, h=0, mi=0, s=0):
    return int(datetime(y, mo, d, h, mi, s, tzinfo=timezone.utc).timestamp()) * 1000


def fmt_ms(ms, utc):
    dt = datetime.fromtimestamp(ms // 1000, tz=timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + ".%03d" % (ms % 1000) + ("Z" if utc else "")


def _dst_periods(rule, year):
    # transitions at 02:00 local standard time (start) and 02:00 local daylight time (end)
    if rule == "us":
        return [((year, 3, 8), (year, 11, 1))] if year == 2026 else [((year, 3, 9), (year, 11, 2))]
    if rule == "eu":
        return [((year, 3, 29), (year, 10, 25))] if year == 2026 else [((year, 3, 30), (year, 10, 26))]
    return []


def zone_record(name):
    z = ZONE_POOL[name]
    periods = []
    if z["dst"] is not None:
        for (s, e) in _dst_periods(z["rule"], 2026):
            start = ms_of(*s) + 2 * 3600000 - z["std"] * 60000
            end = ms_of(*e) + 2 * 3600000 - z["dst"] * 60000
            periods.append((start, end))
    return {"std": z["std"], "dst": z["dst"] if z["dst"] is not None else z["std"], "periods": periods}


def zone_offset_min(zrec, utc_ms):
    for (s, e) in zrec["periods"]:
        if s <= utc_ms < e:
            return zrec["dst"]
    return zrec["std"]


class _Offsets:
    """Difference constraints x_to - x_from in [lo, hi], x_ref = 0, |x| <= 19."""

    def __init__(self, nodes, ref):
        self.nodes = list(nodes)
        self.idx = {n: i for i, n in enumerate(self.nodes)}
        self.ref = self.idx[ref]
        k = len(self.nodes)
        inf = 10 ** 9
        self.d = [[0 if i == j else inf for j in range(k)] for i in range(k)]
        for i in range(k):
            if i != self.ref:
                self._edge(self.ref, i, OFFSET_LIMIT, self.d)
                self._edge(i, self.ref, OFFSET_LIMIT, self.d)

    @staticmethod
    def _edge(u, v, w, d):
        k = len(d)
        if d[u][v] <= w:
            return
        du = [d[i][u] for i in range(k)]
        dv = d[v]
        for i in range(k):
            a = du[i] + w
            if a >= 10 ** 8:
                continue
            row = d[i]
            for j in range(k):
                b = a + dv[j]
                if b < row[j]:
                    row[j] = b

    def try_add(self, frm, to, lo, hi):
        u, v = self.idx[frm], self.idx[to]
        d = [row[:] for row in self.d]
        self._edge(u, v, hi, d)
        self._edge(v, u, -lo, d)
        if any(d[i][i] < 0 for i in range(len(d))):
            return False
        self.d = d
        return True

    def solution(self):
        out = {}
        for n, i in self.idx.items():
            low, high = -self.d[i][self.ref], self.d[self.ref][i]
            out[n] = (low, high)
        return out


def line_bounds(sent_local, recv_local):
    diff = recv_local - sent_local
    lo = -((TRANSIT_MAX_MS - diff) // 1000)   # ceil((diff - 4999) / 1000)
    hi = diff // 1000
    return lo, hi


def segment_transfers(nodes, ref, lines, key="sent"):
    """lines: (xfer_id, frm, sent_local, to, recv_local). Greedy maximal
    consistent runs in stamp order; each run must pin every node."""
    order = sorted(lines, key=lambda t: (t[2] if key == "sent" else t[4], t[0]))
    epochs = []
    cur = _Offsets(nodes, ref)
    first = last = None
    for ln in order:
        lo, hi = line_bounds(ln[2], ln[4])
        stamp = ln[2] if key == "sent" else ln[4]
        if not cur.try_add(ln[1], ln[3], lo, hi):
            epochs.append((first, last, cur.solution()))
            cur = _Offsets(nodes, ref)
            if not cur.try_add(ln[1], ln[3], lo, hi):
                raise ValueError("transfer line admits no offsets")
            first = None
        if first is None:
            first = stamp
        last = stamp
    epochs.append((first, last, cur.solution()))
    return epochs


def _csv_text(header, rows):
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(header)
    for r in rows:
        w.writerow(r)
    return buf.getvalue()


def _half_up_div(num, den):
    return (2 * num + den) // (2 * den)


class Extract:
    pass


def _gen_ids(rng, prefix, count, width, used):
    out = []
    while len(out) < count:
        v = prefix + "".join(rng.choice("0123456789abcdef") for _ in range(width))
        if v not in used:
            used.add(v)
            out.append(v)
    return out


def build_world(seed, prof):
    rng = random.Random(seed)
    w = Extract()
    w.prof = prof
    y, mo, d = prof["start"]
    w.p0 = ms_of(y, mo, d)
    w.ndays = prof["days"]
    w.p1 = w.p0 + w.ndays * MS_DAY
    used = set()
    # zones
    w.zone_names = list(prof["zones"])
    w.zones = {z: zone_record(z) for z in w.zone_names}
    # nodes
    regions = list(prof["regions"])
    nn = prof["nodes"]
    per = {r: 0 for r in regions}
    w.nodes = []
    w.node_region = {}
    for i in range(nn):
        r = regions[i % len(regions)]
        per[r] += 1
        nid = "cq-%s%02d" % (r[0], rng.randint(10, 99))
        while nid in used:
            nid = "cq-%s%02d" % (r[0], rng.randint(10, 99))
        used.add(nid)
        w.nodes.append(nid)
        w.node_region[nid] = r
    w.ref = rng.choice(w.nodes)
    # products
    lines = list(prof.get("product_lines", PRODUCT_LINES[:5]))
    w.products = {}
    for pid in _gen_ids(rng, "dp-", prof["products"], 4, used):
        w.products[pid] = rng.choice(lines)
    # plans and versions
    w.plans = {}
    for code in prof["plans"]:
        free, minb, block, peak, off = PLAN_POOL[code]
        prev = {"version": code + "/2025-09", "from": ms_of(2025, 9, 1),
                "free": free, "minb": minb, "block": block, "peak": peak, "off": off}
        cur_from = w.p0 - MS_DAY * rng.randint(2, 9) + rng.randint(0, 23) * 3600000 + rng.randint(0, 59) * 60000
        cur = {"version": code + "/" + fmt_ms(cur_from, True)[:7], "from": cur_from,
               "free": free + rng.choice([-1, 1, 2]) * (free // 8), "minb": minb, "block": block,
               "peak": peak + 2 * rng.randint(20, 160), "off": off + 2 * rng.randint(10, 80)}
        w.plans[code] = [prev, cur]
    w.prior_p0 = min(v[1]["from"] for v in w.plans.values()) - 3 * MS_DAY
    w.prior_p0 -= w.prior_p0 % MS_DAY
    # tenants
    w.tenants = {}
    seg_pool = list(prof.get("segments", SEGMENTS))
    for tid in _gen_ids(rng, "tn-", prof["tenants"], 4, used):
        w.tenants[tid] = {"segment": rng.choice(seg_pool), "plan": rng.choice(prof["plans"]),
                          "zone": rng.choice(w.zone_names), "name": "Tenant " + tid[3:].upper()}
    w.rng = rng
    w.used = used
    return w


def _quiet(ms):
    t = ms % MS_DAY
    return QUIET_START_MS - 1000 <= t <= QUIET_END_MS + 1000


def _span_quiet(a, b):
    day = a - a % MS_DAY
    while day <= b:
        qs, qe = day + QUIET_START_MS - 1000, day + QUIET_END_MS + 1000
        if a <= qe and b >= qs:
            return True
        day += MS_DAY
    return False


def add_nodes(w, count, seed):
    rng = random.Random(seed * 13 + 5)
    used = set(w.nodes) | set(w.products) | set(w.tenants)
    regions = sorted(set(w.node_region.values()))
    for _ in range(count):
        r = rng.choice(regions)
        nid = "cq-%s%02d" % (r[0], rng.randint(10, 99))
        while nid in used:
            nid = "cq-%s%02d" % (r[0], rng.randint(10, 99))
        used.add(nid)
        w.nodes.append(nid)
        w.node_region[nid] = r


def build_queries(w):
    rng, prof = w.rng, w.prof
    w.queries = []   # dicts with true start S, dur, node, tenant, product, scanned, status
    qids = set()
    tids = sorted(w.tenants)
    prods = sorted(w.products)
    for tid in tids:
        t = w.tenants[tid]
        free = w.plans[t["plan"]][1]["free"]
        nodes_pref = rng.sample(w.nodes, min(len(w.nodes), rng.randint(2, 4)))
        for day in range(w.ndays):
            if rng.random() < 0.12:
                continue
            load = int(free * rng.uniform(0.35, 2.3))
            nq = rng.randint(prof["qmin"], prof["qmax"])
            base = w.p0 + day * MS_DAY
            zoff = zone_offset_min(w.zones[t["zone"]], base) * 60000
            bursts = [base + rng.randint(5 * 3600, 22 * 3600) * 1000 - zoff for _ in range(rng.randint(2, 4))]
            for k in range(nq):
                b = rng.choice(bursts)
                s = b + rng.randint(0, 900) * 1000 + rng.randint(0, 999)
                dur = int(rng.lognormvariate(9.5, 1.3))
                dur = max(120, min(dur, 1500000))
                if _span_quiet(s, s + dur) or s < w.p0 + 60000 or s + dur >= w.p1 - 60000:
                    continue
                scanned = max(1, int(load / nq * rng.uniform(0.15, 2.4)))
                if not prof.get("shipped") and rng.random() < 0.07:
                    scanned = rng.randint(1, 130000000)
                if prof.get("big") and rng.random() < 0.08:
                    scanned = rng.randint(2 * 1024, 7 * 1024) * GIB + rng.randint(0, GIB)
                st = rng.random()
                status = "ok" if st < 0.9 else ("cancelled" if st < 0.95 else "failed")
                qid = "q-%07d" % rng.randint(0, 9999999)
                while qid in qids:
                    qid = "q-%07d" % rng.randint(0, 9999999)
                qids.add(qid)
                w.queries.append({"qid": qid, "S": s, "dur": dur, "node": rng.choice(nodes_pref),
                                  "tenant": tid, "product": rng.choice(prods), "scanned": scanned,
                                  "status": status})
    w.qids = qids


def offset_at(w, node, true_ms):
    off = w.base_off[node]
    for (n, at, new) in w.steps:
        if n == node and true_ms >= at:
            off = new
    return off


def draw_base_offsets(w):
    w.base_off = {}
    for n in w.nodes:
        w.base_off[n] = 0 if n == w.ref else w.rng.choice([v for v in range(-17, 18) if v != 0])
    w.steps = []


def plan_steps(w):
    rng, prof = random.Random(w.step_seed), w.prof
    w.steps = []
    kind = prof.get("steps")
    if not kind:
        return
    members = [n for n in w.nodes if n != w.ref]
    days = list(range(1, w.ndays))
    rng.shuffle(days)

    def new_value(old):
        cands = [v for v in range(-OFFSET_LIMIT, OFFSET_LIMIT + 1) if 3 <= abs(v - old) <= 14]
        return rng.choice(cands)

    def at(day):
        return w.p0 + day * MS_DAY + STEP_AT_MS

    if kind == "one":
        n = rng.choice(members)
        w.steps.append((n, at(days[0]), new_value(w.base_off[n])))
    elif kind == "two":
        if rng.random() < 0.5:
            n = rng.choice(members)
            d1, d2 = sorted(days[:2])
            v1 = new_value(w.base_off[n])
            w.steps.append((n, at(d1), v1))
            w.steps.append((n, at(d2), new_value(v1)))
        else:
            a, b = rng.sample(members, 2)
            w.steps.append((a, at(days[0]), new_value(w.base_off[a])))
            w.steps.append((b, at(days[1]), new_value(w.base_off[b])))
    elif kind == "several":
        k = min(len(members), len(days), rng.randint(3, 4))
        for n, dd in zip(rng.sample(members, k), days[:k]):
            w.steps.append((n, at(dd), new_value(w.base_off[n])))
    elif kind == "back":
        n = rng.choice(members)
        d1, d2 = sorted(days[:2])
        v1 = new_value(w.base_off[n])
        w.steps.append((n, at(d1), v1))
        w.steps.append((n, at(d2), w.base_off[n]))
        if len(members) > 1 and len(days) > 2 and rng.random() < 0.5:
            m = rng.choice([x for x in members if x != n])
            w.steps.append((m, at(days[2]), new_value(w.base_off[m])))
    w.steps.sort(key=lambda s: s[1])


def _local(w, node, true_ms):
    return true_ms + offset_at(w, node, true_ms) * 1000


def _pinned(w, lines, cap=TRANSIT_MAX_MS):
    solver = _Offsets(w.nodes, w.ref)
    for (frm, to, t, tr) in lines:
        d = _local(w, to, t + tr) - _local(w, frm, t)
        lo, hi = -((cap - d) // 1000), d // 1000
        if not solver.try_add(frm, to, lo, hi):
            return False
    return all(lo == hi for lo, hi in solver.solution().values())


def _edge_lines(w, a, b, lines):
    """Lines whose transit sits exactly on a stated limit, and a pin pair that only the 4999 ms cap closes."""
    rng = w.rng

    def when():
        while True:
            t = rng.randint(a, b - 10000)
            if not (_quiet(t) or _quiet(t + 5000)):
                return t

    base = list(lines)
    for tr in (0, TRANSIT_MAX_MS):
        frm, to = rng.sample(w.nodes, 2)
        base.append((frm, to, when(), tr))
    candidates = [n for n in w.nodes if n != w.ref]
    rng.shuffle(candidates)
    for node in candidates:
        pair = [(w.ref, node, when(), 4000), (w.ref, node, when(), rng.randint(0, 999))]
        if rng.random() < 0.5:
            pair = [(node, w.ref, when(), 4000), (node, w.ref, when(), rng.randint(0, 999))]
        out = base + pair
        # thin the other lines touching that node until the 4000 ms line is needed
        rng.shuffle(out)
        for cand in list(out):
            if cand in pair or node not in (cand[0], cand[1]):
                continue
            trial = [x for x in out if x is not cand]
            if _pinned(w, trial):
                out = trial
        if _pinned(w, out) and not _pinned(w, out, TRANSIT_MAX_MS + 1):
            return out
    raise RuntimeError("no pin pair closes on the transit cap")


def build_transfers(w):
    rng, prof = w.rng, w.prof
    w.lines = []
    xid = [0]

    def add(frm, to, sent_true, transit):
        xid[0] += 1
        w.lines.append(("x-%06d" % (rng.randint(0, 999999) * 0 + xid[0] * 7919 % 1000003), frm, _local(w, frm, sent_true),
                        to, _local(w, to, sent_true + transit)))

    cuts = [w.p0] + [s[1] for s in w.steps] + [w.p1]
    epochs = []
    for i in range(len(cuts) - 1):
        a = cuts[i] + (STEP_GAP_MS + 60000 if i > 0 else 0)
        b = cuts[i + 1] - (STEP_GAP_MS + 60000 if i + 1 < len(cuts) - 1 else 0)
        epochs.append((a, b))
    per_epoch = prof.get("lines_per_epoch", 60)
    for (a, b) in epochs:
        solver = None
        tries = 0
        local_lines = []
        while True:
            tries += 1
            for _ in range(per_epoch if not local_lines else 6):
                frm, to = rng.sample(w.nodes, 2)
                t = rng.randint(a, b)
                if _quiet(t) or _quiet(t + 5000):
                    continue
                local_lines.append((frm, to, t, rng.randint(0, TRANSIT_MAX_MS)))
            solver = _Offsets(w.nodes, w.ref)
            for (frm, to, t, tr) in local_lines:
                sl, rl = _local(w, frm, t), _local(w, to, t + tr)
                lo, hi = line_bounds(sl, rl)
                assert solver.try_add(frm, to, lo, hi)
            sol = solver.solution()
            if all(lo == hi for lo, hi in sol.values()):
                break
            if tries > 400:
                raise RuntimeError("cannot pin epoch")
        if prof.get("weak"):
            # drop lines while the epoch stays pinned, so only joint propagation closes it
            rng.shuffle(local_lines)
            keep = list(local_lines)
            for cand in list(local_lines):
                trial = [x for x in keep if x is not cand]
                s2 = _Offsets(w.nodes, w.ref)
                for (frm, to, t, tr) in trial:
                    lo, hi = line_bounds(_local(w, frm, t), _local(w, to, t + tr))
                    s2.try_add(frm, to, lo, hi)
                if all(lo == hi for lo, hi in s2.solution().values()):
                    keep = trial
            local_lines = keep
        if not prof.get("shipped"):
            local_lines = _edge_lines(w, a, b, local_lines)
        for (frm, to, t, tr) in local_lines:
            add(frm, to, t, tr)
    # boundary lines around each clock step
    for (node, c, new) in w.steps:
        others = [n for n in w.nodes if n != node]
        old = None
        for (n2, at2, v2) in w.steps:
            pass
        old = offset_at(w, node, c - 1)
        delta = new - old
        # a consistent pre-step line involving the stepped node
        p = rng.choice(others)
        add(node, p, c - STEP_GAP_MS - rng.randint(5000, 50000), rng.randint(0, TRANSIT_MAX_MS))
        # the first line after the step involves the stepped node and no old offset fits it
        q = rng.choice(others)
        t = c + STEP_GAP_MS + rng.randint(1000, 8000)
        if rng.random() < 0.5:
            # stepped node receives: implied transit shifts by +delta*1000
            tr = rng.randint(max(0, 5000 - delta * 1000), TRANSIT_MAX_MS) if delta > 0 else rng.randint(0, min(TRANSIT_MAX_MS, -delta * 1000 - 1))
            add(q, node, t, tr)
        else:
            tr = rng.randint(0, min(TRANSIT_MAX_MS, delta * 1000 - 1)) if delta > 0 else rng.randint(max(0, 5000 + delta * 1000), TRANSIT_MAX_MS)
            add(node, q, t, tr)
    # renumber ids deterministically and unique
    ids = _gen_ids(rng, "x-", len(w.lines), 6, set())
    w.lines = [(ids[i],) + tuple(ln[1:]) for i, ln in enumerate(w.lines)]


def check_transfers(w):
    """Every epoch pinned, segmentation by either stamp recovers the true steps."""
    want = []
    cuts = [w.p0] + [s[1] for s in w.steps] + [w.p1]
    for i in range(len(cuts) - 1):
        mid = (cuts[i] + cuts[i + 1]) // 2
        want.append({n: offset_at(w, n, mid) for n in w.nodes})
    for key in ("sent", "recv"):
        got = segment_transfers(w.nodes, w.ref, w.lines, key)
        assert len(got) == len(want), (key, len(got), len(want))
        for (first, last, sol), exp in zip(got, want):
            for n in w.nodes:
                assert sol[n] == (exp[n], exp[n]), (key, n, sol[n], exp[n])
    # every node stamps in every epoch
    for i in range(len(cuts) - 1):
        seen = set()
        for ln in w.lines:
            tt = ln[2] - offset_at(w, ln[1], ln[2]) * 1000
            if cuts[i] <= tt < cuts[i + 1]:
                seen.add(ln[1])
                seen.add(ln[3])
        assert seen == set(w.nodes), ("epoch nodes", i)
    # no query activity of a stepped node close to its step
    for (node, c, new) in w.steps:
        for q in w.queries:
            if q["node"] == node:
                assert q["S"] + q["dur"] < c - STEP_GAP_MS - 60000 or q["S"] > c + STEP_GAP_MS + 60000


def build_merges(w):
    rng, prof = w.rng, w.prof
    w.merges = []   # (absorbed, survivor, effective_ms)
    tids = sorted(w.tenants)
    rng.shuffle(tids)
    n = prof.get("merges", 1)
    taken = set()
    for i in range(n):
        a = tids.pop()
        s = tids.pop() if not (prof.get("chain") and i == 1 and w.merges) else w.merges[0][1]
        if s == a:
            s = tids.pop()
        eff = w.p0 + rng.randint(1, w.ndays - 2) * MS_DAY + rng.randint(9, 16) * 3600000 + rng.randint(0, 3599) * 1000
        if prof.get("chain") and i == 1:
            # the earlier survivor is itself absorbed later
            first_a, first_s, first_eff = w.merges[0]
            a = first_s
            s = tids.pop()
            eff = first_eff + rng.randint(1, 2) * MS_DAY // 2 + rng.randint(0, 3599) * 1000
            if eff >= w.p1 - 3600000:
                eff = first_eff + 3 * 3600000
        if a in taken:
            continue
        taken.add(a)
        w.merges.append((a, s, eff))


def build_versions_in_period(w):
    rng, prof = w.rng, w.prof
    if not prof.get("version_change"):
        return
    for code in sorted(w.plans)[: prof.get("version_change")]:
        cur = w.plans[code][-1]
        at = w.p0 + rng.randint(1, w.ndays - 1) * MS_DAY + rng.randint(4, 20) * 3600000 + rng.randint(0, 3599) * 1000
        nxt = dict(cur)
        nxt["version"] = code + "/" + fmt_ms(at, True)[:10]
        nxt["from"] = at
        nxt["free"] = cur["free"] + rng.choice([-2, -1, 1, 3]) * (cur["free"] // 10)
        nxt["block"] = rng.choice([cur["block"], cur["block"] * 2])
        nxt["minb"] = cur["minb"] * rng.choice([1, 2])
        nxt["peak"] = cur["peak"] + 2 * rng.randint(30, 200) + 0
        nxt["off"] = cur["off"] + 2 * rng.randint(15, 90)
        w.plans[code].append(nxt)


def build_corrections(w):
    rng, prof = w.rng, w.prof
    w.corrections = []
    pool = [q for q in w.queries if q["status"] != "failed"]
    rng.shuffle(pool)
    cid = [0]

    def rec(q, action, at, scanned=None):
        cid[0] += 1
        w.corrections.append({"correction_id": "c-%05d" % (cid[0] * 37 % 99991), "query_id": q if isinstance(q, str) else q["qid"],
                              "recorded_at": at, "action": action, "scanned_bytes": scanned})

    def later(q, k=1):
        return q["S"] + q["dur"] + rng.randint(3600, 40 * 3600) * 1000 * k + rng.randint(0, 999)

    simple = prof.get("corr_simple", 5)
    for _ in range(simple):
        q = pool.pop()
        if rng.random() < 0.8:
            val = max(1, int(q["scanned"] * rng.uniform(0.4, 1.8)))
            if prof.get("shipped_bytes"):
                grain = max(v["block"] for vs in w.plans.values() for v in vs)
                val = _round_up(max(val, max(v["minb"] for vs in w.plans.values() for v in vs)), grain)
            rec(q, "restate", later(q), val)
        else:
            rec(q, "void", later(q))
    rec("q-%07d" % rng.randint(0, 9999999), "restate", w.p0 + MS_DAY, 4 * GIB)
    for _ in range(prof.get("corr_revert", 0)):
        q = pool.pop()
        t1 = later(q)
        rec(q, "void", t1)
        rec(q, "reinstate", t1 + rng.randint(600, 7200) * 1000)
        q2 = pool.pop()
        t2 = later(q2)
        rec(q2, "restate", t2, max(1, q2["scanned"] * 3))
        rec(q2, "restate", t2 + rng.randint(600, 7200) * 1000, q2["scanned"])
        q3 = pool.pop()
        t3 = later(q3)
        rec(q3, "restate", t3, max(1, q3["scanned"] // 3))
        rec(q3, "restate", t3 + rng.randint(600, 7200) * 1000, max(1, q3["scanned"] * 2))
    if not prof.get("shipped"):
        q4 = pool.pop()
        t4 = later(q4)
        rec(q4, "void", t4)
        rec(q4, "reinstate", t4)
    ids = _gen_ids(rng, "c-", len(w.corrections), 5, set())
    for c, i in zip(w.corrections, ids):
        c["correction_id"] = i


def build_rejects(w):
    rng = w.rng
    w.rejects = []
    q = rng.choice(w.queries)
    base = [q["node"], q["tenant"], q["product"], fmt_ms(q["S"] + 3600000, False), "5000", str(64 * MIB), "ok"]
    variants = [
        (0, "cq-z00"), (1, "tn-zzzz"), (2, "dp-zzzz"), (5, "12.5"), (4, "-40"),
        (3, fmt_ms(q["S"], False).replace("T", " ")), (6, "running"),
    ]
    for k in range(w.prof.get("rejects", 4)):
        pos, val = variants[k % len(variants)]
        row = list(base)
        row[pos] = val
        qid = "q-%07d" % rng.randint(0, 9999999)
        while qid in w.qids:
            qid = "q-%07d" % rng.randint(0, 9999999)
        w.qids.add(qid)
        w.rejects.append([qid] + row)


def _files_from_world(w, docs):
    rng = w.rng
    f = {}
    f.update(docs)
    nodes = [[n, w.node_region[n], "reference" if n == w.ref else "member"] for n in w.nodes]
    rng.shuffle(nodes)
    if w.prof.get("messy"):
        nodes = [[n, r.capitalize() if i % 2 else r, role.capitalize() if role == "reference" else role]
                 for i, (n, r, role) in enumerate(nodes)]
    f["nodes.csv"] = _csv_text(["node_id", "region", "role"], nodes)
    trows = [[t, v["name"], v["segment"].upper() if (w.prof.get("messy") and i % 3 == 0) else v["segment"], v["plan"], v["zone"]]
             for i, (t, v) in enumerate(w.tenants.items())]
    rng.shuffle(trows)
    f["tenants.csv"] = _csv_text(["tenant_id", "display_name", "segment", "plan", "zone"], trows)
    f["tenant_merges.csv"] = _csv_text(["absorbed_tenant", "surviving_tenant", "effective_at"],
                                       [[a, s, fmt_ms(e, True)] for a, s, e in w.merges])
    prows = [[p, line.upper() if (w.prof.get("messy") and i % 3 == 0) else line, "Dataset " + p[3:].upper()]
             for i, (p, line) in enumerate(w.products.items())]
    rng.shuffle(prows)
    f["products.csv"] = _csv_text(["product_id", "product_line", "name"], prows)

    def plan_json(plans):
        out = {}
        for code in sorted(plans):
            out[code] = [{"version": v["version"], "effective_from": fmt_ms(v["from"], True), "daily_free_bytes": v["free"],
                          "min_billable_bytes": v["minb"], "block_bytes": v["block"], "peak_micros_per_gib": v["peak"],
                          "offpeak_micros_per_gib": v["off"]} for v in plans[code]]
        return out

    f["plans.json"] = json.dumps({"plans": plan_json(w.plans)}, indent=2, sort_keys=True) + "\n"
    draft = {}
    for code, vs in w.plans.items():
        dv = []
        for v in vs:
            v2 = dict(v)
            v2["peak"] = v["peak"] + 2 * rng.randint(1, 40)
            v2["free"] = v["free"] + rng.choice([0, v["free"] // 16])
            dv.append(v2)
        draft[code] = dv
    f["plans_v2_draft.json"] = json.dumps({"revision": 2, "plans": plan_json(draft)}, indent=2, sort_keys=True) + "\n"
    zones = {}
    for name in w.zone_names:
        z = w.zones[name]
        zones[name] = {"standard_offset_minutes": z["std"], "daylight_offset_minutes": z["dst"],
                       "daylight_periods": [{"start": fmt_ms(s, True), "end": fmt_ms(e, True)} for s, e in z["periods"]],
                       "holidays": sorted(w.holidays.get(name, []))}
    f["zones.json"] = json.dumps({"zones": zones}, indent=2, sort_keys=True) + "\n"
    qrows = []
    for q in w.queries:
        status = q["status"]
        st = q.get("render_status", status)
        qrows.append([q.get("render_qid", q["qid"]), q.get("render_node", q["node"]), q.get("render_tenant", q["tenant"]),
                      q["product"], fmt_ms(_local(w, q["node"], q["S"]), False), str(q["dur"]), str(q["scanned"]), st])
    qrows.extend(w.rejects)
    if w.prof.get("messy"):
        for row in qrows:
            if rng.random() < 0.06:
                row[7] = rng.choice([row[7].upper(), row[7].capitalize()])
            if rng.random() < 0.04:
                row[2] = " " + row[2]
            if rng.random() < 0.04:
                row[3] = row[3] + " "
        for row in nodes:
            pass
    rng.shuffle(qrows)
    pos = {row[0].strip(): i for i, row in enumerate(qrows)}
    for first, second in getattr(w, "tie_file", []):
        i, j = pos[first], pos[second]
        if i < j:
            qrows[i], qrows[j] = qrows[j], qrows[i]
            pos[first], pos[second] = j, i
    f["queries.csv"] = _csv_text(["query_id", "node_id", "tenant_id", "product_id", "started_local", "duration_ms",
                                  "scanned_bytes", "status"], qrows)
    lines = ["# inter-node stage transfer journal", "# xfer_id|from_node|sent_local|to_node|recv_local"]
    tl = list(w.lines)
    rng.shuffle(tl)
    for i, (x, a, s, b, r) in enumerate(tl):
        lines.append("%s|%s|%s|%s|%s" % (x, a, fmt_ms(s, False), b, fmt_ms(r, False)))
        if i % 97 == 41:
            lines.append("")
    f["transfers.log"] = "\n".join(lines) + "\n"
    cl = list(w.corrections)
    rng.shuffle(cl)
    f["corrections.jsonl"] = "".join(json.dumps({"action": c["action"], "correction_id": c["correction_id"],
                                                 "query_id": c["query_id"], "recorded_at": fmt_ms(c["recorded_at"], True),
                                                 "scanned_bytes": c["scanned_bytes"]}, sort_keys=True) + "\n" for c in cl)
    f["allowance_statement_prior.csv"] = _csv_text(
        ["billing_day", "tenant_id", "query_id", "node_id", "started_at", "billed_at", "metered_bytes", "free_bytes"],
        w.statement)
    f["invoice_preview.json"] = json.dumps(w.preview, indent=2, sort_keys=True) + "\n"
    return f


def _round_up(v, block):
    return -(-v // block) * block


def build_statement(w):
    """Allowance statement for the three days before the earliest current rate card."""
    rng = w.rng
    rows = []
    tids = sorted(w.tenants)
    rng.shuffle(tids)
    nodes = sorted(w.nodes)
    used = set()
    pairs = {}
    kinds = ["A", "B", "D", None, None]
    for i, tid in enumerate(tids[:5]):
        t = w.tenants[tid]
        ver = w.plans[t["plan"]][0]
        zrec = w.zones[t["zone"]]
        day0 = w.prior_p0 + (i % 3) * MS_DAY
        lstart = day0 - zone_offset_min(zrec, day0) * 60000
        free, block, minb = ver["free"], ver["block"], ver["minb"]
        n_before = rng.randint(2, 4)
        n_after = rng.randint(1, 3)
        before = [_round_up(max(minb, int(free / (n_before + 1) * rng.uniform(0.6, 1.2))), block) for _ in range(n_before)]
        while sum(before) >= free:
            before[-1] = _round_up(max(minb, before[-1] // 2), block)
            if before[-1] <= minb:
                before.pop()
        left = free - sum(before)
        kind = kinds[i]
        if kind is None:
            pair = [_round_up(max(minb, left + rng.randint(1, 50) * block), block)]
        else:
            lo = _round_up(left + block, block)
            mp = max(lo, _round_up(max(minb, left + rng.randint(2, 30) * block), block))
            mq = mp if kind in ("B", "D") else mp + rng.randint(3, 40) * block
            pair = [mp, mq]
        after = [_round_up(max(minb, int(free * rng.uniform(0.05, 0.4))), block) for _ in range(n_after)]
        t_cursor = lstart + rng.randint(8 * 3600, 10 * 3600) * 1000
        events = []
        for m in before:
            t_cursor += rng.randint(300, 3000) * 1000 + rng.randint(0, 999)
            events.append((t_cursor, m, None))
        t_cursor += rng.randint(300, 3000) * 1000 + rng.randint(0, 999)
        tie_b = t_cursor
        if kind is None:
            events.append((tie_b, pair[0], None))
        else:
            events.append((tie_b, pair[0], "p"))
            events.append((tie_b, pair[1], "q"))
        for m in after:
            t_cursor += rng.randint(300, 3000) * 1000 + rng.randint(0, 999)
            events.append((t_cursor, m, None))
        recs = []
        for (b, m, role) in events:
            dur = rng.randint(5000, 600000)
            qid = "pq-%07d" % rng.randint(0, 9999999)
            while qid in used:
                qid = "pq-%07d" % rng.randint(0, 9999999)
            used.add(qid)
            recs.append({"b": b, "m": m, "role": role, "dur": dur, "qid": qid, "node": rng.choice(nodes)})
        if kind is not None:
            p = [r for r in recs if r["role"] == "p"][0]
            q = [r for r in recs if r["role"] == "q"][0]
            lo_id, hi_id = sorted([p["qid"], q["qid"]])
            n_lo, n_hi = nodes[0], nodes[-1]
            if kind == "A":
                # true first (smaller metered) has the larger id, the later start and the later node
                p["qid"], q["qid"] = hi_id, lo_id
                p["dur"] = rng.randint(9000, 180000) + rng.randint(0, 999)
                q["dur"] = p["dur"] + rng.randint(60000, 400000) + rng.randint(0, 999)
                p["node"], q["node"] = n_hi, n_lo
            elif kind == "B":
                # equal metered: the earlier start goes first; it has the larger id and later node
                p["qid"], q["qid"] = hi_id, lo_id
                q["dur"] = rng.randint(9000, 180000) + rng.randint(0, 999)
                p["dur"] = q["dur"] + rng.randint(60000, 400000) + rng.randint(0, 999)
                p["node"], q["node"] = n_hi, n_lo
            else:
                # equal metered: the earlier start goes first; it has the smaller id and earlier node
                p["qid"], q["qid"] = lo_id, hi_id
                q["dur"] = rng.randint(9000, 180000) + rng.randint(0, 999)
                p["dur"] = q["dur"] + rng.randint(60000, 400000) + rng.randint(0, 999)
                p["node"], q["node"] = n_lo, n_hi
        recs.sort(key=lambda r: (r["b"], r["m"], r["b"] - r["dur"], r["qid"]))
        left = free
        day = datetime.fromtimestamp((recs[0]["b"] + zone_offset_min(zrec, recs[0]["b"]) * 60000) // 1000, tz=timezone.utc).date()
        for r in recs:
            got = min(left, r["m"])
            left -= got
            row = [day.isoformat(), tid, r["qid"], r["node"], fmt_ms(r["b"] - r["dur"], True),
                   fmt_ms(r["b"], True), str(r["m"]), str(got)]
            rows.append(row)
            if r["role"]:
                pairs.setdefault(tid, {})[r["role"]] = row
    rng.shuffle(rows)
    for roles in pairs.values():
        # the row billed second is listed first
        ip, iq = rows.index(roles["p"]), rows.index(roles["q"])
        if ip < iq:
            rows[ip], rows[iq] = rows[iq], rows[ip]
    w.statement = rows


def build_holidays(w):
    rng, prof = w.rng, w.prof
    w.holidays = {}
    for name in w.zone_names:
        w.holidays[name] = ["2026-01-01", "2026-12-25"]
    if prof.get("holiday"):
        z = rng.choice(w.zone_names)
        for d in range(w.ndays):
            day = datetime.fromtimestamp((w.p0 + d * MS_DAY) // 1000, tz=timezone.utc).date()
            if day.weekday() < 5 and d > 0:
                w.holidays[z].append(day.isoformat())
                break


def build_preview(w):
    totals = {}
    asof = min(v[0]["from"] for v in w.plans.values()) + 20 * MS_DAY
    for q in w.queries:
        if q["status"] == "failed":
            continue
        v = w.plans[w.tenants[q["tenant"]]["plan"]][0]
        totals[q["tenant"]] = totals.get(q["tenant"], 0) + q["scanned"] * v["peak"] // GIB + 7
    w.preview = {
        "title": "Invoice preview",
        "authority": "authoritative preview of tenant charges for the billing period",
        "rate_card_as_of": fmt_ms(asof, True)[:10],
        "period_from": fmt_ms(w.p0, True)[:10],
        "period_to": fmt_ms(w.p1 - MS_DAY, True)[:10],
        "tenants": [{"tenant_id": t, "charge_micros": totals[t]} for t in sorted(totals)],
    }


def _new_qid(w):
    rng = w.rng
    qid = "q-%07d" % rng.randint(0, 9999999)
    while qid in w.qids:
        qid = "q-%07d" % rng.randint(0, 9999999)
    w.qids.add(qid)
    return qid


def _add_query_ending(w, tenant, end_ms, status="ok"):
    rng = w.rng
    for _ in range(40):
        dur = rng.randint(2000, 900000)
        s = end_ms - dur
        if not _span_quiet(s, end_ms) and w.p0 + 60000 <= s and end_ms < w.p1 - 60000:
            node = rng.choice(w.nodes)
            q = {"qid": _new_qid(w), "S": s, "dur": dur, "node": node, "tenant": tenant,
                 "product": rng.choice(sorted(w.products)), "status": status,
                 "scanned": rng.randint(1, 40) * w.plans[w.tenants[tenant]["plan"]][-1]["block"] + rng.randint(1, 999)}
            w.queries.append(q)
            return q
    raise RuntimeError("no room for boundary query")


def plant_boundaries(w):
    rng, prof = w.rng, w.prof
    w.planted = set()
    if not prof.get("boundaries"):
        return
    for (a, s, eff) in w.merges:
        w.planted.add(_add_query_ending(w, a, eff)["qid"])
    for code, vs in w.plans.items():
        for v in vs:
            if w.p0 < v["from"] < w.p1:
                tens = [t for t in sorted(w.tenants) if w.tenants[t]["plan"] == code]
                if tens:
                    w.planted.add(_add_query_ending(w, rng.choice(tens), v["from"])["qid"])
    tens = sorted(w.tenants)
    for local_h in (8, 20, 0):
        t = rng.choice(tens)
        z = w.zones[w.tenants[t]["zone"]]
        for d in range(1, w.ndays):
            mid = w.p0 + d * MS_DAY
            day = datetime.fromtimestamp(mid // 1000, tz=timezone.utc).date()
            if day.weekday() >= 5:
                continue
            u = mid + local_h * 3600000 - zone_offset_min(z, mid) * 60000
            if zone_offset_min(z, u) != zone_offset_min(z, mid):
                continue
            w.planted.add(_add_query_ending(w, t, u)["qid"])
            break
    # a voided query: correction voids it, plus one void on a failed query
    return


def make_files(w, docs):
    return _files_from_world(w, docs)


def _group_recs(eng):
    groups = {}
    for r in eng.billed_recs:
        groups.setdefault((r["ident"], r["day"]), []).append(r)
    for recs in groups.values():
        recs.sort(key=lambda r: (r["b"], r["metered"], r["start"], r["q"]["qid"]))
    return groups


def plant_ties(w, eng, want):
    rng = w.rng
    byq = {q["qid"]: q for q in w.queries}
    corrected = {c["query_id"] for c in w.corrections}
    groups = _group_recs(eng)
    keys = sorted(groups, key=lambda k: (k[0], k[1].isoformat()))
    rng.shuffle(keys)
    made = []
    for key in keys:
        if len(made) >= want:
            break
        recs = groups[key]
        for i in range(len(recs) - 1):
            a, b = recs[i], recs[i + 1]
            if not (0 < a["free"] < a["metered"]):
                continue
            qa, qb = byq.get(a["q"]["qid"]), byq.get(b["q"]["qid"])
            if qa is None or qb is None or qa["qid"] in corrected or qb["qid"] in corrected:
                continue
            if qa["qid"] in w.planted or qb["qid"] in w.planted:
                continue
            if a["q"]["node"] == b["q"]["node"] and rng.random() < 0.7:
                continue
            new_dur = b["b"] - a["start"]
            if new_dur > 1500000 or _span_quiet(qa["S"], qa["S"] + new_dur):
                continue
            equal = len(made) % 3 == 2
            left = a["free"]
            if not equal:
                if a["metered"] == b["metered"]:
                    continue
                first, second = (a, b) if a["metered"] < b["metered"] else (b, a)
                if first["start"] <= second["start"]:
                    continue
            elif a["start"] == b["start"]:
                continue
            if equal:
                if left >= 2 * b["metered"] or a["ver"] != b["ver"]:
                    continue
                qa["scanned"] = qb["scanned"]
            qa["dur"] = new_dur
            w.planted.add(qa["qid"])
            w.planted.add(qb["qid"])
            made.append((qa["qid"], qb["qid"], equal))
            break
    return made


def plant_halves(w, eng, want):
    rng = w.rng
    byq = {q["qid"]: q for q in w.queries}
    corrected = {c["query_id"] for c in w.corrections}
    made = 0
    recs = list(eng.billed_recs)
    rng.shuffle(recs)
    for r in recs:
        if made >= want:
            break
        q = byq.get(r["q"]["qid"])
        if q is None or q["qid"] in corrected or q["qid"] in w.planted or r["free"] != 0:
            continue
        rate = r["ver"][5] if r["peak"] else r["ver"][6]
        for m in range(rng.randint(0, 40), 400):
            c = (2 * m + 1) << 29
            k = ((2 * m + 1) * rate - 1) // 2
            if k % 2 == 0 and c >= r["ver"][3] and c % r["ver"][4] == 0:
                q["scanned"] = c
                w.planted.add(q["qid"])
                made += 1
                break


def _truth_offsets_ok(w, eng):
    for q in w.queries:
        local = _local(w, q["node"], q["S"])
        assert eng.offset_for(q["node"], local) == offset_at(w, q["node"], q["S"]), q["qid"]


def _tie_pairs(eng):
    for recs in _group_recs(eng).values():
        for i in range(len(recs) - 1):
            if recs[i]["b"] == recs[i + 1]["b"]:
                yield recs[i], recs[i + 1]


def _order_tie_ids(w, eng):
    """Give the query billed first in each tie the larger id."""
    byq = {q["qid"]: q for q in w.queries}
    swapped = False
    for r1, r2 in _tie_pairs(eng):
        q1, q2 = byq[r1["q"]["qid"]], byq[r2["q"]["qid"]]
        if q1["qid"] < q2["qid"]:
            q1["qid"], q2["qid"] = q2["qid"], q1["qid"]
            swapped = True
    return swapped


def _assert_ties_bite(eng):
    cross = equal = 0
    for r1, r2 in _tie_pairs(eng):
        f1, f2, m1, m2 = r1["free"], r2["free"], r1["metered"], r2["metered"]
        partial = f1 < m1 or f2 < m2
        pool = f1 + f2
        if not (partial and pool > 0 and min(pool, m2) != f2):
            continue
        assert r1["q"]["qid"] > r2["q"]["qid"]
        if m1 < m2 and r1["start"] > r2["start"]:
            cross += 1
        elif m1 == m2 and r1["start"] < r2["start"]:
            equal += 1
    assert cross >= 1 and equal >= 1, (cross, equal)


def _assert_common(w, eng, ties):
    _truth_offsets_ok(w, eng)
    tie_pairs = {frozenset((a, b)) for a, b, _ in ties}
    for key, recs in _group_recs(eng).items():
        for i in range(len(recs) - 1):
            if recs[i]["b"] == recs[i + 1]["b"]:
                assert frozenset((recs[i]["q"]["qid"], recs[i + 1]["q"]["qid"])) in tie_pairs, key
                if i + 2 < len(recs):
                    assert recs[i + 2]["b"] != recs[i]["b"]
    # statement replays under the stated allowance rule and the tie order
    days = {}
    for row in w.statement:
        days.setdefault((row[0], row[1]), []).append(row)
    for (day, tid), rows in days.items():
        ver = w.plans[w.tenants[tid]["plan"]][0]
        rows = sorted(rows, key=lambda r: (r[5], int(r[6]), r[4], r[2]))
        left = ver["free"]
        for r in rows:
            got = min(left, int(r[6]))
            left -= got
            assert got == int(r[7])


def _assert_shipped(w, eng):
    for key, recs in _group_recs(eng).items():
        bs = [r["b"] for r in recs]
        assert len(bs) == len(set(bs))
    effs = {e for _, _, e in w.merges}
    froms = {v["from"] for vs in w.plans.values() for v in vs}
    for r in eng.billed_recs:
        assert r["b"] not in effs and r["b"] not in froms
        day, tod = eng.local_parts(r["zone"], r["b"])
        assert tod not in (0, 8 * 3600000, 20 * 3600000)
        rate = r["ver"][5] if r["peak"] else r["ver"][6]
        assert (2 * r["charge_bytes"] * rate) % (1 << 31) != (1 << 30)
        assert r["charge_bytes"] * rate < (1 << 53)
        assert r["metered"] == r["q"]["scanned"]
    for z in w.zones.values():
        for s, e in z["periods"]:
            for t in (s, e):
                assert not (w.p0 - 2 * MS_DAY <= t <= w.p1 + 2 * MS_DAY)
    per = {}
    for c in w.corrections:
        per[c["query_id"]] = per.get(c["query_id"], 0) + 1
    assert max(per.values()) == 1
    assert not w.steps


def make_extract(seed, prof, docs, engine_cls):
    last = None
    for attempt in range(40):
        try:
            return _make(seed * 101 + attempt, prof, docs, engine_cls)
        except (AssertionError, RuntimeError, IndexError, ValueError, KeyError) as exc:
            last = exc
            continue
    raise RuntimeError("extract generation failed: %r" % (last,))


def _make(seed, prof, docs, engine_cls):
    w = build_world(seed, prof)
    if prof.get("extra_nodes"):
        add_nodes(w, prof["extra_nodes"], seed)
    w.step_seed = seed * 7 + 3
    draw_base_offsets(w)
    build_queries(w)
    plan_steps(w)
    build_versions_in_period(w)
    if prof.get("shipped_bytes"):
        grain = max(v["block"] for vs in w.plans.values() for v in vs)
        floor = max(v["minb"] for vs in w.plans.values() for v in vs)
        for q in w.queries:
            q["scanned"] = _round_up(max(q["scanned"], floor), grain)
    build_merges(w)
    build_holidays(w)
    build_corrections(w)
    build_rejects(w)
    build_statement(w)
    build_transfers(w)
    check_transfers(w)
    plant_boundaries(w)
    build_preview(w)
    files = make_files(w, docs)
    eng = engine_cls(files)
    eng.compute()
    ties = []
    if prof.get("ties"):
        ties = plant_ties(w, eng, prof["ties"])
        assert len(ties) >= min(prof["ties"], 2)
        files = make_files(w, docs)
        eng = engine_cls(files)
        eng.compute()
    if prof.get("halves"):
        plant_halves(w, eng, prof["halves"])
        files = make_files(w, docs)
        eng = engine_cls(files)
        eng.compute()
    if prof.get("shipped"):
        for _ in range(30):
            bad = [r for r in eng.billed_recs
                   if (2 * r["charge_bytes"] * (r["ver"][5] if r["peak"] else r["ver"][6])) % (1 << 31) == (1 << 30)]
            if not bad:
                break
            byq = {q["qid"]: q for q in w.queries}
            for r in bad:
                byq[r["q"]["qid"]]["scanned"] += grain
            files = make_files(w, docs)
            eng = engine_cls(files)
            eng.compute()
    if ties:
        swapped = _order_tie_ids(w, eng)
        if swapped:
            files = make_files(w, docs)
            eng = engine_cls(files)
            eng.compute()
        _assert_ties_bite(eng)
        # in each tie the query billed second is listed first in queries.csv
        w.tie_file = [(r1["q"]["qid"], r2["q"]["qid"]) for r1, r2 in _tie_pairs(eng)]
        files = make_files(w, docs)
        eng = engine_cls(files)
        eng.compute()
        _assert_ties_bite(eng)
    _assert_common(w, eng, ties)
    if prof.get("shipped"):
        _assert_shipped(w, eng)
    w.ties = ties
    return files, eng, w


