APP = Path("/app")
OUT_DIR = APP / "out"
PROGRAM = OUT_DIR / "transform.py"
CALL_LIMIT_SEC = 60
SHIPPED_SEED = 6336032076212419930 % 1000003
REPORT_NAMES = sorted(
    ["normalized.jsonl", "summary.json", "data_quality.json", "product_summary.json"]
    + ["region_%s.json" % r for r in REGIONS]
    + ["segment_%s.json" % s for s in SEGMENTS]
)
DOC_NAMES = ["metering_standard.md", "record_dictionary.md", "report_layout.md"]
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_LOCK = threading.RLock()
_CACHE: dict[str, object] = {}

_WRAPPER = r'''
import json, os, runpy, sys
_log = open(sys.argv[1], "a", buffering=1, encoding="utf-8")
_program = sys.argv[2]

def _note(*items):
    try:
        _log.write(json.dumps([str(i) for i in items]) + "\n")
    except Exception:
        pass

def _hook(event, args):
    if event == "open":
        path, mode, flags = args
        if isinstance(path, int):
            return
        try:
            path = os.path.abspath(os.fsdecode(path))
        except Exception:
            return
        writes = bool(mode and any(ch in str(mode) for ch in "wax+"))
        if mode is None and isinstance(flags, int):
            writes = bool(flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_APPEND | os.O_TRUNC))
        _note("write" if writes else "read", path)
    elif event.startswith("socket."):
        _note("net", event)
    elif event in ("os.remove", "os.rename", "os.rmdir", "os.mkdir", "os.truncate", "os.chmod",
                   "os.symlink", "os.link", "shutil.rmtree", "shutil.move", "os.utime", "os.chown"):
        try:
            _note("write", os.path.abspath(os.fsdecode(args[0])))
        except Exception:
            pass

sys.addaudithook(_hook)
sys.argv = [_program] + sys.argv[3:]
sys.path.insert(0, os.path.dirname(_program))
runpy.run_path(_program, run_name="__main__")
'''


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _grant_read(argument: str) -> None:
    """Make an agent-written path readable before the uid drop.

    Agent editors write through a temp file and rename it, so a program the agent
    wrote can land at mode 0600. The checks run it as an unprivileged user, so the
    verifier (root) widens the mode of the program, its siblings and its parents.
    This changes no graded content.
    """
    if not argument.startswith("/app"):
        return
    path = Path(argument)
    if not path.exists():
        return
    try:
        targets = [path]
        if path.is_file():
            targets += [p for p in path.parent.rglob("*") if p.is_file() or p.is_dir()]
        for target in targets:
            target.chmod(target.stat().st_mode | (0o555 if target.is_dir() else 0o444))
        for parent in path.parents:
            parent.chmod(parent.stat().st_mode | 0o555)
            if str(parent) == "/app":
                break
    except OSError:
        pass


def _untrusted_command(command: list[str]) -> list[str]:
    if os.name != "posix" and _root_only_tests_present():
        raise RuntimeError("verifier isolation requires POSIX uid/gid dropping")
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        for argument in command:
            _grant_read(argument)
        return [*_SETPRIV, *command]
    return command


def _nobody_ids() -> tuple[int, int]:
    try:
        import grp
        import pwd
        return pwd.getpwnam("nobody").pw_uid, grp.getgrnam("nogroup").gr_gid
    except (ImportError, KeyError):
        return 65534, 65534


_NOBODY = _nobody_ids()


def _reap_untrusted() -> None:
    """Kill every process left running as the untrusted user, so nothing outlives its run."""
    if os.name != "posix" or os.geteuid() != 0:
        return
    for _round in range(3):
        alive = []
        for entry in os.listdir("/proc"):
            if not entry.isdigit():
                continue
            try:
                with open("/proc/%s/status" % entry, encoding="utf-8") as fh:
                    uid_line = next(line for line in fh if line.startswith("Uid:"))
            except (OSError, StopIteration):
                continue
            if int(uid_line.split()[1]) == _NOBODY[0]:
                alive.append(int(entry))
        if not alive:
            return
        for pid in alive:
            try:
                os.kill(pid, signal.SIGKILL)
            except OSError:
                pass


def _scratch_root() -> Path:
    with _LOCK:
        if "root" not in _CACHE:
            root = Path(tempfile.mkdtemp(prefix="qfm-grade-"))
            root.chmod(0o755)
            wrapper = root / "audit_wrap.py"
            wrapper.write_text(_WRAPPER, encoding="utf-8")
            wrapper.chmod(0o644)
            _CACHE["root"] = root
        return _CACHE["root"]


def _shipped_files() -> dict[str, str]:
    with _LOCK:
        if "shipped_files" not in _CACHE:
            files = {}
            for rel, blob in _SHIPPED_DATA.items():
                files[Path(rel).name] = zlib.decompress(base64.b64decode(blob)).decode("utf-8")
            _CACHE["shipped_files"] = files
        return _CACHE["shipped_files"]


def _shipped_expected() -> dict[str, str]:
    with _LOCK:
        if "shipped_expected" not in _CACHE:
            engine = RefEngine(_shipped_files())
            _CACHE["shipped_expected"] = engine.compute()
        return _CACHE["shipped_expected"]


def _hidden_seed(base) -> int:
    return SHIPPED_SEED if base == "shipped" else base * 7777


def _hidden(index: int) -> tuple[dict[str, str], dict[str, str]]:
    key = "hidden-%d" % index
    with _LOCK:
        if key not in _CACHE:
            name, base, profile = HIDDEN_PROFILES[index]
            docs = {n: _shipped_files()[n] for n in DOC_NAMES}
            files, engine, _world = make_extract(_hidden_seed(base), profile, docs, RefEngine)
            _CACHE[key] = (files, engine.reports())
        return _CACHE[key]


def _digest(folder: Path) -> str:
    h = hashlib.sha256()
    for p in sorted(folder.rglob("*")):
        h.update(str(p.relative_to(folder)).encode())
        if p.is_file():
            h.update(p.read_bytes())
    return h.hexdigest()


def _run(tag: str, files: dict[str, str], data_rel: str, out_rel: str, cwd_rel: str | None,
         reuse: str | None = None) -> dict:
    """Run the delivered program once on an extract, as nobody, under the audit hook.

    With reuse, the run repeats in the directories of an earlier run (same extract
    path, output path and working directory) after its output directory is cleared.
    """
    with _LOCK:
        if tag in _CACHE:
            return _CACHE[tag]
        result = {"ok": False, "stdout": "", "reports": {}, "events": [], "data": "", "out": "",
                  "intact": True, "base": ""}
        try:
            root = _scratch_root()
            if reuse:
                base = Path(reuse)
                shutil.rmtree(base / out_rel, ignore_errors=True)
                data = base / data_rel
            else:
                base = Path(tempfile.mkdtemp(prefix="run-", dir=root))
                base.chmod(0o777)
                data = base / data_rel
                data.mkdir(parents=True)
                for name, text in files.items():
                    (data / name).write_bytes(text.encode("utf-8"))
                    (data / name).chmod(0o644)
                for d in [data, *data.parents]:
                    if d == base:
                        break
                    d.chmod(0o755)
            result["base"] = str(base)
            out = base / out_rel
            out.parent.mkdir(parents=True, exist_ok=True)
            for d in [out.parent, *out.parent.parents]:
                if d == base:
                    break
                d.chmod(0o777)
            cwd = base / cwd_rel if cwd_rel else Path("/")
            cwd.mkdir(parents=True, exist_ok=True)
            cwd.chmod(0o777)
            log = base / "audit.log"
            log.write_text("", encoding="utf-8")
            log.chmod(0o666)
            if os.name == "posix" and os.geteuid() == 0:
                log.chmod(0o600)
                os.chown(log, _NOBODY[0], _NOBODY[1])
            before = _digest(data)
            result["data"], result["out"] = str(data), str(out)
            if not PROGRAM.is_file():
                _CACHE[tag] = result
                return result
            command = _untrusted_command([sys.executable, "-I", "-B", str(root / "audit_wrap.py"), str(log),
                                          str(PROGRAM), str(data), str(out)])
            env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "HOME": str(base)}
            try:
                proc = subprocess.run(command, cwd=str(cwd), env=env, capture_output=True,
                                      timeout=CALL_LIMIT_SEC, start_new_session=True)
                finished = proc.returncode == 0
                result["stdout"] = proc.stdout.decode("utf-8", "replace")
            except subprocess.TimeoutExpired:
                finished = False
            finally:
                _reap_untrusted()
            result["intact"] = _digest(data) == before
            try:
                for line in log.read_text(encoding="utf-8", errors="replace").splitlines():
                    try:
                        result["events"].append(json.loads(line))
                    except ValueError:
                        continue
            except OSError:
                pass
            reports = {}
            for name in REPORT_NAMES:
                path = out / name
                if path.is_file():
                    reports[name] = path.read_bytes()
            result["reports"] = reports
            result["ok"] = finished
        except Exception:
            result["ok"] = False
        _CACHE[tag] = result
        return result


def _run_shipped(variant: str) -> dict:
    layouts = {
        "a": ("extract/data", "reports/out", "work"),
        "a2": ("extract/data", "reports/out", "work"),
        "b": ("deep/copy/of/the/extract", "elsewhere/metering", None),
    }
    data_rel, out_rel, cwd_rel = layouts[variant]
    reuse = _run_shipped("a")["base"] if variant == "a2" else None
    return _run("shipped-" + variant, _shipped_files(), data_rel, out_rel, cwd_rel, reuse)


def _run_hidden(index: int) -> dict:
    files, _expected = _hidden(index)
    return _run("hidden-run-%d" % index, files, "x%02d/in" % index, "x%02d/out" % index, "x%02d" % index)


def _all_runs() -> list[dict]:
    runs = [_run_shipped("a"), _run_shipped("a2"), _run_shipped("b")]
    runs += [_run_hidden(i) for i in range(len(HIDDEN_PROFILES))]
    return runs


def _reports_match(run: dict, expected: dict[str, str]) -> bool:
    if not run["ok"]:
        return False
    for name in REPORT_NAMES:
        if run["reports"].get(name) != expected[name].encode("utf-8"):
            return False
    return True


def _hidden_check(index: int) -> bool:
    try:
        _files, expected = _hidden(index)
        return _reports_match(_run_hidden(index), expected)
    except Exception:
        return False


def _delivered_exact(name: str) -> bool:
    try:
        return (OUT_DIR / name).read_bytes() == _shipped_expected()[name].encode("utf-8")
    except Exception:
        return False


def _python_tree() -> list[str]:
    roots = {sys.prefix, sys.base_prefix, sys.exec_prefix, sys.base_exec_prefix}
    return sorted({os.path.realpath(r) for r in roots} | set(roots))


_RUNTIME_PREFIXES = ("/dev/", "/proc/self/", "/usr/share/zoneinfo/", "/usr/lib/locale/", "/etc/localtime")
_THIRD_PARTY_MARKERS = ("/site-packages/", "/dist-packages/")


def _inside(path: str, folder: str) -> bool:
    folder = folder.rstrip("/")
    return path == folder or path.startswith(folder + "/")


def _is_third_party(path: str) -> bool:
    return any(marker in path for marker in _THIRD_PARTY_MARKERS)


def _is_runtime(path: str) -> bool:
    if path.startswith(_RUNTIME_PREFIXES):
        return True
    return any(_inside(path, prefix) for prefix in _python_tree()) and not _is_third_party(path)


def _own(run: dict, path: str) -> bool:
    return _inside(path, run["data"]) or _inside(path, run["out"]) or _inside(path, str(OUT_DIR))


